static slice__u8 module__PRELUDE = {(u8*)"enum AllocatorMode { Alloc, Free, Resize, FreeAll }\012\012// An allocator: (data, mode, size, alignment, old_memory, old_size) -> memory\012//   Alloc    `size` bytes of zeroed memory, aligned to `alignment`\012//   Free     frees `old_memory`, returns null\012//   Resize   `size` bytes holding the first min(size, old_size) bytes of\012//            `old_memory`, the rest zeroed; `old_memory` is freed\012//   FreeAll  frees everything the allocator handed out, if it can\012// Running out of memory returns null. `alignment` is a power of two.\012type AllocatorProc = fn(*void, AllocatorMode, isize, isize, *void, isize) -> *void;\012\012struct Allocator {\012    procedure: AllocatorProc;\012    data: *void;                // passed to `procedure`\012}\012\012struct Context {\012    allocator: Allocator;        // the heap, unless a block changes it\012    temp_allocator: Allocator;   // an arena: free it all with FreeAll\012    logger: Logger;              // where std/log's log() goes: stderr\012    log_level: LogLevel;         // log() skips what's below it: Debug, all of it\012    panic_handler: PanicHandler; // what std's panic and assert call\012}\012\012enum LogLevel { Debug, Info, Warning, Error }\012\012// A logger: (data, level, message). The message is only valid during the\012// call, so a logger that keeps it copies it.\012type LoggerProc = fn(*void, LogLevel, string);\012\012struct Logger {\012    procedure: LoggerProc;\012    data: *void;                // passed to `procedure`\012}\012\012// What std's panic and assert call: (data, what, message, location), with\012// `what` \"panic\" or \"assertion failed\" and the location \"file:line:col\".\012// It shouldn't return: if it does, the program aborts there anyway, since\012// the code after a panic can't go on.\012type PanicProc = fn(*void, string, string, string);\012\012struct PanicHandler {\012    procedure: PanicProc;\012    data: *void;                // passed to `procedure`\012}\012\012// ---- type information, for printing any value (std/fmt) and reflection\012//\012// type_info(T) is a *TypeInfo; the compiler makes one for every type that\012// needs it, at run time and at compile time. A value of any type converts\012// to Any implicitly: a pointer to (a copy of) it and its type.\012\012enum TypeKind {\012    Void, Bool, Int, Float, Rawptr, Pointer, Array, Slice, Growable, String,\012    Function, Struct, Union, Enum, TaggedEnum,\012}\012\012struct TypeInfo {\012    kind: TypeKind;\012    name: string;             // as messages write it, like []u8 or List(i32)\012    size: isize;\012    align: isize;\012    is_signed: bool;          // Int\012    elem: *TypeInfo;          // Pointer, Array, Slice, Growable, String:\012                              // what it holds; Enum, TaggedEnum: the tag's\012                              // integer type\012    count: isize;             // Array: its length\012    fields: []TypeField;      // Struct, Union; TaggedEnum: tag and payload\012    variants: []TypeVariant;  // Enum, TaggedEnum\012}\012\012struct TypeField {\012    name: string;\012    info: *TypeInfo;\012    offset: isize;\012}\012\012struct TypeVariant {\012    name: string;\012    value: i64;\012    payload: *TypeInfo;       // TaggedEnum: what it holds, or null\012}\012\012struct Any {\012    value: *void;\012    info: *TypeInfo;\012}\012\012// ---- the temp allocator: one arena per program, freed all at once\012\012// ---- the target: what the program is built for, for `#if`:\012//   #if (OS == .Windows) { ... } else { ... }\012enum OperatingSystem { Linux, MacOS, Windows, FreeBSD, Other }\012enum Architecture { X64, Arm64, X86, Arm32, RiscV64, Other }\012const OS = OperatingSystem.Linux;\012const ARCH = Architecture.X64;\012const POINTER_SIZE = sizeof(*void);\012\012// ---- Error: one type every error enum converts to\012//\012// An error enum, `enum IoError: Error { NotFound, ... }`, has Error's None\012// at 0 and converts to Error implicitly, so `or_return` passes failures of\012// any enum on from a function returning Error, and `fn main() -> Error`\012// reports what failed. The value is which enum it came from (a number the\012// compiler gives each one, in the high 32 bits) and the variant's value\012// (the low 32); each enum's None is Error's None. Back is a checked match:\012// `if (err is IoError(e))`, `case IoError(.NotFound):`.\012\012enum Error: u64 { None }\012\012// A value that may be missing: `\?T` is short for Option(T). A new one is\012// None, and `o or_else fallback` is its value, or the fallback for None.\012enum Option($T) { None, Some(T) }\012\012// the failure enum `e` came from, or null for None\012fn error_enum(e: Error) -> *TypeInfo {\012    return sabk_error_type(((e as u64) >> 32) as u32);\012}\012\012// the value of the variant `e` came from\012fn error_value(e: Error) -> i64 {\012    return ((e as u64) & 0xFFFFFFFF) as i64;\012}\012\012#scope_file\012\012// ---- type information, for printing any value (std/fmt) and reflection\012//\012// type_info(T) is a *TypeInfo; the compiler makes one for every type that\012// needs it, at run time and at compile time. A value of any type converts\012// to Any implicitly: a pointer to (a copy of) it and its type.\012\012extern fn calloc(count: usize, size: usize) -> *void;\012extern fn realloc(memory: *void, size: usize) -> *void;\012extern fn free(memory: *void);\012extern fn memset(memory: *void, value: i32, size: usize) -> *void;\012extern fn memcpy(dst: *void, src: *void, size: usize) -> *void;\012\012fn default_context() -> Context {\012    return Context.{\012        .allocator = Allocator.{ .procedure = heap_proc },\012        .temp_allocator = Allocator.{ .procedure = temp_proc },\012        .logger = Logger.{ .procedure = stderr_logger },\012        .log_level = .Debug,\012        .panic_handler = PanicHandler.{ .procedure = print_and_abort },\012    };\012}\012\012// ---- the default logger and panic handler, both on stderr\012\012extern fn dprintf(fd: i32, format: *u8, ...) -> i32;\012extern fn fflush(file: *void) -> i32;\012extern fn abort();\012\012// \"warning: message\"\012fn stderr_logger(data: *void, level: LogLevel, message: string) {\012    let name = \"debug\";\012    switch (level) {\012    case .Debug:   name = \"debug\";\012    case .Info:    name = \"info\";\012    case .Warning: name = \"warning\";\012    case .Error:   name = \"error\";\012    }\012    fflush(null); // after what was printed before it\012    dprintf(2, \"%.*s: %.*s\\n\", name.len as i32, name.ptr, message.len as i32,\012            message.ptr);\012}\012\012// \"file:line:col: panic: message\", then abort()\012fn print_and_abort(data: *void, what: string, message: string, location: string) {\012    fflush(null); // keep what was printed before\012    dprintf(2, \"%.*s: %.*s: %.*s\\n\", location.len as i32, location.ptr,\012            what.len as i32, what.ptr, message.len as i32, message.ptr);\012    abort();\012}\012\012// ---- the heap: C's allocator, which aligns everything to 16 bytes\012\012fn heap_proc(data: *void, mode: AllocatorMode, size: isize, align: isize, old: *void, old_size: isize) -> *void {\012    switch (mode) {\012    case AllocatorMode.Alloc:\012        return calloc(1, size as usize);\012    case AllocatorMode.Free:\012        free(old);\012        return null;\012    case AllocatorMode.Resize:\012        let memory = realloc(old, size as usize);\012        if (memory != null && size > old_size) {\012            let added = (memory as *u8)[old_size..size];\012            memset(added.ptr, 0, added.len as usize);\012        }\012        return memory;\012    default:\012        return null; // FreeAll: the heap can't\012    }\012}\012\012// ---- the temp allocator: one arena per program, freed all at once\012\012struct TempBlock {\012    previous: *TempBlock;\012    memory: []u8;\012    used: isize;\012}\012\012let temp_blocks: *TempBlock = null;\012\012fn align_forward(address: isize, align: isize) -> isize {\012    return (address + align - 1) & ~(align - 1);\012}\012\012// --sanitize: memory taken back is poisoned, and unpoisoned when it's\012// handed out again (the C runtime's; they do nothing in other builds)\012extern fn sabk_poison(memory: *void, size: isize);\012extern fn sabk_unpoison(memory: *void, size: isize);\012\012// `size` bytes from `block`, or null if they don't fit\012fn temp_carve(block: *TempBlock, size: isize, align: isize) -> *void {\012    let base = block.memory.ptr as isize;\012    let start = align_forward(base + block.used, align) - base;\012    if (start + size > block.memory.len)\012        return null;\012    block.used = start + size;\012    let memory = block.memory[start..start + size];\012    sabk_unpoison(memory.ptr, size);\012    memset(memory.ptr, 0, size as usize);\012    return memory.ptr;\012}\012\012fn temp_alloc(size: isize, align: isize) -> *void {\012    if (align == 0)\012        align = 1;\012    if (temp_blocks != null) {\012        let memory = temp_carve(temp_blocks, size, align);\012        if (memory != null)\012            return memory;\012    }\012    let capacity = 64 * 1024;\012    if (size + align > capacity)\012        capacity = size + align;\012    let block = calloc(1, sizeof(TempBlock) as usize) as *TempBlock;\012    let memory = calloc(1, capacity as usize) as *u8;\012    if (block == null || memory == null) {\012        free(block);\012        free(memory);\012        return null;\012    }\012    block.previous = temp_blocks;\012    block.memory = memory[0..capacity];\012    temp_blocks = block;\012    return temp_carve(block, size, align);\012}\012\012// keeps the newest block for reuse and frees the rest\012fn temp_free_all() {\012    if (temp_blocks == null)\012        return;\012    let block = temp_blocks.previous;\012    while (block != null) {\012        let previous = block.previous;\012        sabk_unpoison(block.memory.ptr, block.memory.len); // the heap's again\012        free(block.memory.ptr);\012        free(block);\012        block = previous;\012    }\012    temp_blocks.previous = null;\012    temp_blocks.used = 0;\012    sabk_poison(temp_blocks.memory.ptr, temp_blocks.memory.len);\012}\012\012fn temp_proc(data: *void, mode: AllocatorMode, size: isize, align: isize, old: *void, old_size: isize) -> *void {\012    switch (mode) {\012    case AllocatorMode.Alloc:\012        return temp_alloc(size, align);\012    case AllocatorMode.Resize:\012        let memory = temp_alloc(size, align);\012        if (memory != null && old != null) {\012            let keep = old_size;\012            if (size < keep)\012                keep = size;\012            memcpy(memory, old, keep as usize);\012        }\012        return memory;\012    case AllocatorMode.FreeAll:\012        temp_free_all();\012        return null;\012    default:\012        return null; // Free: arena memory is only freed all at once\012    }\012}\012\012// ---- Error: one type every error enum converts to\012//\012// An error enum, `enum IoError: Error { NotFound, ... }`, has Error's None\012// at 0 and converts to Error implicitly, so `or_return` passes failures of\012// any enum on from a function returning Error, and `fn main() -> Error`\012// reports what failed. The value is which enum it came from (a number the\012// compiler gives each one, in the high 32 bits) and the variant's value\012// (the low 32); each enum's None is Error's None. Back is a checked match:\012// `if (err is IoError(e))`, `case IoError(.NotFound):`.\012\012// the compiler's table of the enums that became Errors\012extern fn sabk_error_type(id: u32) -> *TypeInfo;\012", 10726};
